from pathlib import Path
import json
d=Path(__file__).resolve().parent
p=d/'anatomy_plan.json';plan=json.loads(p.read_text(encoding='utf-8'))
plan['identity']='Floating olive-brown single orb cyclops. One huge ivory eye with amber iris and black vertical pupil, broad fang-filled mouth, curved ivory spikes on the orb perimeter, ochre patches. NO wings, legs, arms, ears or tail. The entire creature is the head sphere.'
p.write_text(json.dumps(plan,ensure_ascii=False,indent=2)+chr(10),encoding='utf-8')
for direction in ['Up','Down']:
    rear=direction=='Up'
    view='Pure REAR/BACK view moving AWAY toward screen UP, elevated orthographic. The complete rounded olive shell and original peripheral ivory spines face viewer, with ochre patches. No eye, teeth, mouth, tongue, nostrils or face anywhere on back.' if rear else 'Pure FRONT view moving TOWARD screen DOWN, elevated orthographic. One centered huge ivory eye with amber iris and vertical pupil ABOVE one centered broad tooth-filled mouth. Match olive-brown source palette and source ivory curved spikes. No three-quarter or sideways eye.'
    parts=['complete spherical creature, normal state, including ALL original ivory spikes, '+('plain rear shell' if rear else 'normal eye and narrowly open mouth with two rows of fangs'), 'identical plain rear orb, SAME silhouette' if rear else 'same complete orb in attack state, large open mouth and two rows of ivory teeth; eye angry; SAME shell and spikes', 'identical plain rear orb, SAME silhouette' if rear else 'same complete orb in death state, CLOSED eye, mouth open with ochre tongue hanging downward, as source death head; SAME shell and spikes', 'ONE small plain olive-brown oval fill patch only, solid opaque, NO spikes, face or extra creature. This connector will be fully hidden inside the complete orb.']
    prompt='Use case: identity-preserve. Production Unity 2D sprite sheet. Image 1 is current original atlas with normal, attack and death expressions; Image 2 current assembled creature. These are identity and style references. '+plan['identity']+chr(10)+view+chr(10)+'Exactly 4 equal columns by 2 equal rows. ONLY the first row has parts, left to right:'+chr(10)+chr(10).join(str(i+1)+'. '+s for i,s in enumerate(parts))+chr(10)+'Second row completely empty. First three orbs same size, centered, identical silhouette and spike placement. Each part inside one cell with generous padding. Preserve broad cartoon cel shading, dark olive outline, muted olive ochre shell, cream spines, single eye and source anatomy. No new limbs or organs or armor. No detached spikes, no separate jaws or tongue cells. Background exactly flat RGB #FF00FF magenta immediately outside outlines, opaque interiors. No ground shadows, floor, vignette, glow, gradient outside parts, text, labels, grid, checkerboard or watermark.'
    (d/'generation'/direction/'prompt.txt').write_text(prompt,encoding='utf-8')
